// Package opcode lists the WebAssembly instruction opcodes, their text names
// and the signatures of the operators whose operands and result are fixed.
//
// An Opcode encodes a prefixed instruction with its prefix byte: an index
// below 0x100 as prefix<<8 | index, a larger one (the relaxed SIMD and half
// precision operators) as prefix<<12 | index. Every opcode in use has exactly
// one encoding, so Opcode values compare and switch as plain integers.
//
// tables.go is generated by internal/opgen from the opcode lists of
// src/wasm/wasm-opcodes.h; portions are derived from V8, Copyright the V8
// project authors, used under the BSD license in ../decoder/V8_LICENSE.
package opcode

import "github.com/go-quickjs/go-quickjs/wasm/internal/module"

// Opcode is an instruction's opcode, its prefix byte included for a prefixed
// instruction.
type Opcode uint32

// The prefix bytes of the prefixed instructions.
const (
	PrefixAsmJS   byte = 0xfa
	PrefixGC      byte = 0xfb
	PrefixNumeric byte = 0xfc
	PrefixSIMD    byte = 0xfd
	PrefixAtomic  byte = 0xfe
)

// IsPrefix reports whether b is a prefix byte.
func IsPrefix(b byte) bool { return b >= PrefixAsmJS && b <= PrefixAtomic }

// Prefixed returns the opcode of the instruction with prefix byte prefix and
// index index, which must be at most 0xfff.
func Prefixed(prefix byte, index uint32) Opcode {
	if index > 0xff {
		return Opcode(prefix)<<12 | Opcode(index)
	}
	return Opcode(prefix)<<8 | Opcode(index)
}

// Prefix returns op's prefix byte, or 0 for an instruction without one.
func (op Opcode) Prefix() byte {
	switch {
	case op < 0x100:
		return 0
	case op < 0x10000:
		return byte(op >> 8)
	}
	return byte(op >> 12)
}

// Name returns op's text name: "i32.add", "struct.new". A prefix byte alone
// is "unknown", and an opcode that names no instruction "invalid opcode".
func (op Opcode) Name() string {
	var s string
	switch {
	case op < 0x100:
		if IsPrefix(byte(op)) {
			return "unknown"
		}
		s = names00[op]
	case op>>8 == 0xfa:
		s = namesFA[op&0xff]
	case op>>8 == 0xfb:
		s = namesFB[op&0xff]
	case op>>8 == 0xfc:
		s = namesFC[op&0xff]
	case op>>8 == 0xfd:
		s = namesFD[op&0xff]
	case op>>8 == 0xfe:
		s = namesFE[op&0xff]
	case op>>8 == 0xfd1:
		s = namesFD1[op&0xff]
	}
	if s == "" {
		return "invalid opcode"
	}
	return s
}

// String returns op's name.
func (op Opcode) String() string { return op.Name() }

// Sig is an operator's signature. Results has at most one type.
type Sig struct {
	Params  []module.ValueType
	Results []module.ValueType
}

type sigIndex uint8

// Signature returns the signature of an operator whose operand and result
// types the opcode alone decides -- the numeric operators, the numeric
// conversions with a 0xfc prefix and the SIMD operators without immediates --
// or nil for any other opcode. The SIMD loads and stores have one too: an
// i32 address, whatever the memory.
func Signature(op Opcode) *Sig {
	var s sigIndex
	switch {
	case op < 0x100:
		s = sigs00[op]
	case op>>8 == 0xfa:
		s = sigsFA[op&0xff]
	case op>>8 == 0xfc:
		s = sigsFC[op&0xff]
	case op>>8 == 0xfd:
		s = sigsFD[op&0xff]
	case op>>8 == 0xfd1:
		s = sigsFD1[op&0xff]
	}
	if s == sigNone {
		return nil
	}
	return &sigs[s]
}

// AtomicSignature returns the signature of an atomic memory operator, with
// an i64 address if memory64, or nil if op is not one.
func AtomicSignature(op Opcode, memory64 bool) *Sig {
	if op>>8 != 0xfe {
		return nil
	}
	s := sigsAtomic32[op&0xff]
	if memory64 {
		s = sigsAtomic64[op&0xff]
	}
	if s == sigNone {
		return nil
	}
	return &sigs[s]
}

// IsRelaxedSIMD reports whether op is in the relaxed SIMD range, 0xfd100 to
// 0xfd1ff, which the half-precision operators share.
func IsRelaxedSIMD(op Opcode) bool { return op&0xfff00 == 0xfd100 }

// IsFP16SIMD reports whether op is a half-precision SIMD operator.
func IsFP16SIMD(op Opcode) bool {
	return (op >= F16x8Splat && op <= F16x8ReplaceLane) || (op >= F16x8Abs && op <= F16x8Qfms)
}
